import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph User + Dev Monthly - June 2026","description":"","frontmatter":{"title":"Ceph User + Dev Monthly - June 2026","date":"2026-06-24T00:00:00.000Z","updated":"2026-06-25T00:00:00.000Z","tags":["Ceph","监控","社区动态","会议纪要","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_User_+_Dev_Monthly_-_June_2026.md","filePath":"posts/2026/Ceph_User_+_Dev_Monthly_-_June_2026.md","lastUpdated":null}'),l={name:"posts/2026/Ceph_User_+_Dev_Monthly_-_June_2026.md"};function n(o,e,s,h,p,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h2><p>本次 Ceph User + Dev Monthly 会议于 2026 年 6 月召开，主要讨论了 Ceph Manager 中 disk prediction 模块的现状与未来方向，以及社区新用户的入门指引。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="_1-disk-prediction-模块现状与新方案" tabindex="-1">1. Disk Prediction 模块现状与新方案 <a class="header-anchor" href="#_1-disk-prediction-模块现状与新方案" aria-label="Permalink to &quot;1. Disk Prediction 模块现状与新方案&quot;">​</a></h3><p>会议首先讨论了 Ceph Manager 中 disk prediction 模块的维护状态。该模块基于 SMART 统计数据预测硬盘故障，但已长期无人维护。</p><p>Frederick 介绍了 Dan Vanderstart 提交的一个全新 disk prediction 模型（分支名：<code>disk_prediction_smart</code>），该模型：</p><ul><li>完全替代原有的 disk prediction 模块</li><li>基于 device health 模块采集的指标数据进行预测分析</li><li>目前仍处于 work-in-progress 状态，最初于 2025 年 8 月展示</li></ul><p><strong>关键讨论点：</strong></p><ul><li><strong>SMART 数据解读的挑战</strong>：不同设备制造商对 SMART 属性的使用方式差异很大，某些属性的原始值需要进行归一化处理（如 100 减去读数值），部分 SSD/NVMe 的 media wear out indicator 容易被误读。</li><li><strong>数据采集限制</strong>：某些硬件控制器（如 Adaptec RAID 卡）可能导致 smartctl 无法正常采集指标，需要将磁盘以 JBOD 模式直连。smartmontools 版本建议至少 7.5。</li><li><strong>与其他监控信号结合</strong>：建议考虑将 device health 监控与 BlueStore slow operations 等已有告警结合，但需注意 BlueStore 慢操作告警不一定指向硬件问题——例如 RGW 集群中 bucket index 的 RocksDB 因 tombstone 过多、缺少 compaction 也可能触发该告警。</li><li><strong>外部工具集成</strong>：有与会者提到可通过 Redfish exporter 从 BMC/ILO 采集硬件健康指标并导出到 Prometheus，作为补充数据源。</li></ul><p><strong>Action Items：</strong></p><ol><li>Laura 将与 Dan 确认是否已有 tracker ticket 用于跟踪此分支的进展，若无则创建一个</li><li>Laura 将与 Yarit Hatuka（Manager 维护者、原 device health 模块维护者）沟通，获取其对新模型的意见</li><li>需确认 device health 模块的维护状态——此前有讨论考虑退休该模块，但新 disk prediction 模型依赖其数据采集能力</li></ol><h3 id="_2-debian-13-上-tentacle-ceph-client-的安装" tabindex="-1">2. Debian 13 上 Tentacle Ceph Client 的安装 <a class="header-anchor" href="#_2-debian-13-上-tentacle-ceph-client-的安装" aria-label="Permalink to &quot;2. Debian 13 上 Tentacle Ceph Client 的安装&quot;">​</a></h3><p>Wannes 提问 Debian 13 上安装 Tentacle Ceph client 的推荐方式。据 Casey 回复，Umbrella 项目将提供 Debian 13 的官方软件包，发布在即。</p><h3 id="_3-新用户入门指引" tabindex="-1">3. 新用户入门指引 <a class="header-anchor" href="#_3-新用户入门指引" aria-label="Permalink to &quot;3. 新用户入门指引&quot;">​</a></h3><p>来自比利时布鲁塞尔的 Wati 作为新成员加入会议。他正在开发一个基于 Django 的项目，技术栈包括 Kubernetes、PostgreSQL、OpenSearch、Redis 和 Celery，正在评估将 Ceph 作为存储方案，目前尚无 Ceph 使用经验。</p><p>社区成员为其推荐了以下入门资源：</p><ul><li><strong>官方文档</strong>：Ceph 官网的 Beginner&#39;s Guide，根据具体使用场景（RGW 对象存储、CephFS 文件存储、RBD 块存储）查阅对应文档</li><li><strong>社区交流渠道</strong>： <ul><li>Ceph users 邮件列表（适合初学者和进阶问题）</li><li>Slack 频道：主频道 #ceph，各子项目专用频道（RGW、CephFS 等），以及新建的 #getting-started 频道</li><li>Reddit r/ceph 社区</li><li>Ceph YouTube 频道（包含大量入门教程和代码深度解析）</li><li>Ceph 社区日历（pad.ceph.com），可订阅各类定期会议</li></ul></li></ul><h3 id="_4-irc-频道存废讨论" tabindex="-1">4. IRC 频道存废讨论 <a class="header-anchor" href="#_4-irc-频道存废讨论" aria-label="Permalink to &quot;4. IRC 频道存废讨论&quot;">​</a></h3><p>Laura 指出 ceph.io 官网的 Connect 页面仍列出 IRC 频道，但自 Slack 普及后使用率大幅下降。会议讨论了是否保留 IRC 链接：</p><ul><li>可能仍有少量忠实用户</li><li>过去存在 IRC-Slack 桥接机器人，但不确定是否仍在运行</li><li>将在年底网站更新时作为待议事项处理，同时查看网站分析数据确认 IRC 链接的点击率</li></ul><h2 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h2><p>本次会议重点聚焦于 Ceph Manager 的 disk prediction 能力重建，新模型基于 device health 数据进行预测，但面临 SMART 数据标准化、硬件兼容性等挑战。社区对新用户保持开放和友好的态度，提供了丰富的入门资源。下次会议将于下月同一时间举行。</p>',22)])])}const u=a(l,[["render",n]]);export{_ as __pageData,u as default};
